#include <stdio.h>
#include <stdlib.h>

typedef struct DNode { int data; struct DNode *prev, *next; } DNode;

void insert_end(DNode **head, int val) {
    DNode *n = malloc(sizeof(DNode));
    n->data = val; n->next = NULL;
    if (!*head) { n->prev = NULL; *head = n; return; }
    DNode *cur = *head;
    while (cur->next) cur = cur->next;
    cur->next = n; n->prev = cur;
}

void print_reverse(DNode *head) {
    if (!head) return;
    while (head->next) head = head->next;
    while (head) { printf("%d ", head->data); head = head->prev; }
    printf("\n");
}

int main() {
    DNode *head = NULL;
    insert_end(&head, 10); insert_end(&head, 20); insert_end(&head, 30);
    print_reverse(head);
    return 0;
}
